REPLACE = {'frontend/src/ConclusionGraph.css': {'before': '25c5c79e2c42dec3db9e5fcdc43ec3752af8f0b66fb70cba4431da2cd0a96849', 'after': '/* Conclusion graph: glass stage cards on an animated flow, in the inspector. */\n\n.cg { margin-bottom: var(--space-5); padding-bottom: var(--space-4); border-bottom: 1px solid var(--separator); }\n.cg-head { display: flex; align-items: center; justify-content: space-between; gap: var(--space-2); margin-bottom: var(--space-3); }\n.cg-head h2 { font-family: var(--font-display); font-size: var(--font-size-md); font-weight: var(--font-weight-semibold);\n              letter-spacing: -0.012em; color: var(--label-1); }\n.cg-foot { margin: var(--space-2) 0 0; font-size: var(--font-size-xxs); line-height: 1.4; color: var(--label-3); }\n\n/* a sideways strip: glass cards left to right, snapping, fading at the edges */\n.cgx-scroll {\n  margin: 0 calc(-1 * var(--space-5)); padding: 6px var(--space-5) 12px;\n  overflow: auto; overscroll-behavior: contain; scroll-snap-type: x proximity; scroll-behavior: smooth;\n  scroll-padding-inline: var(--space-5); scrollbar-width: thin;\n  -webkit-mask-image: linear-gradient(to right, transparent 0, #000 var(--space-5), #000 calc(100% - var(--space-5)), transparent 100%);\n  mask-image: linear-gradient(to right, transparent 0, #000 var(--space-5), #000 calc(100% - var(--space-5)), transparent 100%);\n}\n.cgx-scroll:focus-visible { outline: 3px solid var(--accent-ring); outline-offset: -3px; border-radius: var(--radius-md); }\n.cgx-track { position: relative; display: flex; align-items: flex-start; gap: 30px; width: max-content; padding: 4px 2px; }\n.cgx-col { position: relative; z-index: 1; display: flex; flex-direction: column; gap: 22px; scroll-snap-align: start; }\n\n/* edges: a faint rail, a flowing dash and particles along it; the confirmed path glows */\n.cgx-edges { position: absolute; left: 0; top: 0; overflow: visible; pointer-events: none; z-index: 0; }\n.cgx-edge path { fill: none; stroke-linecap: round; }\n.cgx-edge-base { stroke-width: 1.6; stroke-dasharray: 100; stroke-dashoffset: 100;\n                 animation: cgx-draw 0.9s var(--ease-out) forwards; animation-delay: calc(0.25s + var(--k) * 0.12s); }\n.cgx-edge-flow { stroke-width: 1.6; stroke-dasharray: 3 9; animation: cgx-flow 1.1s linear infinite; opacity: 0.9; }\n.cgx-edge-glow { stroke-width: 6; opacity: 0.35; }\n\n/* the spine\'s stage nodes: a luminous core in a soft halo */\n.cgx-spine-dot { opacity: 0; animation: cgx-fade-in 0.4s ease forwards; animation-delay: calc(var(--k) * 0.12s); }\n.cgx-halo { fill: rgba(10, 132, 255, 0.16); stroke: rgba(90, 200, 250, 0.45); stroke-width: 1; }\n.cgx-core { fill: #0a84ff; filter: drop-shadow(0 0 4px #5ac8fa); }\n.cgx-spine-dot.is-done .cgx-halo { animation: cgx-pulse 2.8s ease-in-out infinite; transform-origin: center; transform-box: fill-box; }\n.cgx-spine-dot.is-abstain .cgx-halo { fill: rgba(255, 159, 10, 0.16); stroke: rgba(255, 196, 110, 0.55); }\n.cgx-spine-dot.is-abstain .cgx-core { fill: #ff9f0a; filter: drop-shadow(0 0 4px #ff9f0a); }\n.cgx-spine-dot.is-pending .cgx-halo { fill: none; stroke: var(--separator-strong); }\n.cgx-spine-dot.is-pending .cgx-core { fill: var(--label-3); filter: none; }\n@keyframes cgx-pulse { 0%, 100% { transform: scale(1); opacity: 1; } 50% { transform: scale(1.25); opacity: 0.55; } }\n.cgx-particle { opacity: 0; animation: cgx-fade-in 0.4s ease forwards; animation-delay: calc(1s + var(--k) * 0.12s); }\n.cgx-edge.is-done .cgx-edge-base, .cgx-edge.is-done .cgx-edge-glow { stroke: url(#cgx-done); }\n.cgx-edge.is-done .cgx-edge-flow { stroke: #bfe6ff; }\n.cgx-edge.is-done .cgx-particle { fill: #e6f6ff; filter: drop-shadow(0 0 3px #5ac8fa) drop-shadow(0 0 6px #0a84ff); }\n.cgx-edge.is-abstain .cgx-edge-base { stroke: rgba(255, 159, 10, 0.75); }\n.cgx-edge.is-abstain .cgx-edge-flow { stroke: #ffd08a; animation-duration: 1.8s; }\n.cgx-edge.is-abstain .cgx-particle { fill: #ffe2b0; filter: drop-shadow(0 0 3px #ff9f0a); }\n.cgx-edge.is-pending .cgx-edge-base { stroke: var(--separator-strong); stroke-dasharray: 2 4; animation: none; stroke-dashoffset: 0; }\n.cgx-edge.is-compare .cgx-edge-base { stroke: var(--label-3); stroke-dasharray: 2 3; animation: none; stroke-dashoffset: 0; }\n@keyframes cgx-draw { to { stroke-dashoffset: 0; } }\n@keyframes cgx-flow { to { stroke-dashoffset: -12; } }\n@keyframes cgx-fade-in { to { opacity: 1; } }\n\n/* glass stage cards */\n.cgx-node {\n  position: relative; display: flex; flex-direction: column; gap: 3px; width: 190px; min-height: 108px;\n  padding: 11px 12px 12px; border: 0; border-radius: 12px; text-align: left; cursor: default; font: inherit; color: var(--label-1);\n  background: linear-gradient(160deg, rgba(255, 255, 255, 0.07), rgba(255, 255, 255, 0.02)), var(--surface-raised);\n  -webkit-backdrop-filter: blur(14px) saturate(150%); backdrop-filter: blur(14px) saturate(150%);\n  box-shadow: 0 0 0 0.5px var(--separator-strong), 0 6px 18px rgba(0, 0, 0, 0.16), inset 0 1px 0 rgba(255, 255, 255, 0.08);\n  opacity: 0; transform: translateY(6px) scale(0.98);\n  animation: cgx-in 0.55s var(--ease-spring) forwards; animation-delay: calc(var(--k) * 0.12s);\n  transition: box-shadow var(--dur-base) ease, transform var(--dur-base) var(--ease-spring);\n}\n/* a gradient hairline around each card, brighter on the confirmed path */\n.cgx-node::before {\n  content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 1px; pointer-events: none;\n  background: linear-gradient(140deg, rgba(255, 255, 255, 0.28), rgba(255, 255, 255, 0.02) 45%, rgba(255, 255, 255, 0.12));\n  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);\n  -webkit-mask-composite: xor; mask-composite: exclude;\n}\n.cgx-node.is-done { box-shadow: 0 0 0 0.5px rgba(10, 132, 255, 0.55), 0 0 22px rgba(10, 132, 255, 0.16), 0 6px 18px rgba(0, 0, 0, 0.16),\n                                inset 0 1px 0 rgba(255, 255, 255, 0.1); }\n.cgx-node.is-done::before { background: linear-gradient(140deg, rgba(90, 200, 250, 0.75), rgba(10, 132, 255, 0.1) 50%, rgba(90, 200, 250, 0.35)); }\n.cgx-node.is-abstain { box-shadow: 0 0 0 0.5px rgba(255, 159, 10, 0.6), 0 0 22px rgba(255, 159, 10, 0.14), 0 6px 18px rgba(0, 0, 0, 0.16); }\n.cgx-node.is-abstain::before { background: linear-gradient(140deg, rgba(255, 196, 110, 0.75), rgba(255, 159, 10, 0.08) 50%, rgba(255, 196, 110, 0.3)); }\n.cgx-node.is-compare { min-height: 0; background: transparent; -webkit-backdrop-filter: none; backdrop-filter: none;\n                       box-shadow: none; outline: 1px dashed var(--separator-strong); outline-offset: -1px; }\n.cgx-node.is-compare::before { display: none; }\n.cgx-node.is-pending { opacity: 0.6; }\n.cgx-node:hover { transform: translateY(-2px); }\n.cgx-node:active { transform: scale(0.98); }\n.cgx-node:focus-visible { outline: 3px solid var(--accent-ring); outline-offset: 2px; }\n\n/* the finding: filled, as the conclusion of the flow */\n.cgx-node.is-final.is-done { background: linear-gradient(150deg, #1f8fff, #0a6cff 60%, #0a54d6); color: #fff;\n  box-shadow: 0 0 0 0.5px rgba(160, 210, 255, 0.8), 0 0 30px rgba(10, 132, 255, 0.45), 0 8px 22px rgba(0, 0, 0, 0.25); }\n.cgx-node.is-final.is-done .cgx-title, .cgx-node.is-final.is-done .cgx-detail { color: rgba(255, 255, 255, 0.85); }\n.cgx-node.is-final.is-done .cgx-dot { background: rgba(255, 255, 255, 0.25); }\n.cgx-node.is-final.is-abstain { background: linear-gradient(150deg, rgba(255, 159, 10, 0.28), rgba(255, 159, 10, 0.12)); }\n\n.cgx-head { display: flex; align-items: center; gap: 7px; margin-bottom: 3px; }\n.cgx-dot { flex: none; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 9px; display: grid; place-items: center;\n           font-family: var(--font-mono); font-size: 10px; font-weight: var(--font-weight-semibold); color: #fff; background: var(--accent);\n           box-shadow: 0 0 8px rgba(10, 132, 255, 0.55); }\n.cgx-node.is-abstain .cgx-dot { background: var(--status-orange); box-shadow: 0 0 8px rgba(255, 159, 10, 0.55); }\n.cgx-node.is-pending .cgx-dot, .cgx-node.is-compare .cgx-dot { background: var(--fill-pressed); color: var(--label-1); box-shadow: none; }\n.cgx-title { font-size: var(--font-size-xs); font-weight: var(--font-weight-semibold); letter-spacing: 0.01em; color: var(--label-2); }\n.cgx-value { font-size: var(--font-size-base); font-weight: var(--font-weight-medium); line-height: 1.3; overflow-wrap: anywhere; }\n.cgx-value.is-mono { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }\n.cgx-detail { font-size: var(--font-size-xs); line-height: 1.35; color: var(--label-2); }\n@keyframes cgx-in { to { opacity: 1; transform: none; } }\n.cgx-node.is-pending { animation-name: cgx-in-dim; }\n@keyframes cgx-in-dim { to { opacity: 0.6; transform: none; } }\n\n/* the evidence card a node jumps to flashes once */\n/* the evidence card a node jumps to: a ring drawn OUTSIDE the card, with room around\n   it, above its sticky header - an edge shadow hugged the text and was clipped */\n.panel.cg-flash { position: relative; }\n.panel.cg-flash::after {\n  content: ""; position: absolute; inset: 6px -14px; z-index: 5; border-radius: 16px; pointer-events: none;\n  box-shadow: 0 0 0 1.5px rgba(10, 132, 255, 0.85), 0 0 26px rgba(10, 132, 255, 0.28), inset 0 0 18px rgba(10, 132, 255, 0.08);\n  animation: cg-card-flash 1.7s var(--ease-out) forwards;\n}\n@keyframes cg-card-flash { 0%, 35% { opacity: 1; } 100% { opacity: 0; } }\n\n@media (prefers-reduced-motion: reduce) {\n  .cgx-edge-flow, .cgx-particle { display: none; }\n  .cgx-spine-dot, .cgx-spine-dot .cgx-halo { animation: none; opacity: 1; }\n  .cgx-edge-base, .cgx-node { animation: none; opacity: 1; transform: none; stroke-dashoffset: 0; }\n}\n\n/* Case Finding is a raised card with its own box: its ring follows that box -\n   an even margin on every side, corners parallel to the card\'s - instead of the\n   text-hugging offsets used for the plain cards */\n.panel.finding.cg-flash::after { inset: -6px; border-radius: calc(var(--radius-xl) + 6px); }\n'}}
CL_OLD = "popover's ranking link and the graph's replay stage open the forward-replay view.\n"
CL_NEW = "popover's ranking link and the graph's replay stage open the forward-replay view.\n\nThe jump-to-evidence ring around Case Finding now follows that card's own box - an even\nmargin on every side, corners parallel to the card's - like the ring around every other card.\n"
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing")
    if read(p) == v["after"]: skipped += 1
    elif sha(p) == v["before"]: writes[p] = v["after"]
    else: abort(f"{p} is not the version this patch was written for; send its sha256")
cl = read("CHANGELOG.md")
if CL_NEW in cl: skipped += 1
elif cl.count(CL_OLD) == 1: writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else: abort("CHANGELOG.md: the patch 25 entry this appends after was not found")
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
print(f"patch 26: {len(writes)} files written, {skipped} already in place.")
